// Writes the variables of when conditions, from when.json, as Go for the manifest check and the core,
// and as TypeScript for the SDK. Run by `make lib_protocol_generate`; the generated files are committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { variables } = JSON.parse(read('../when.json'))
const HEADER =
  'Code generated by libs/core/protocol/tools/when.mjs from libs/core/protocol/when.json. DO NOT EDIT.'
const GO_TYPES = { bool: 'kindBool', string: 'kindString', map: 'kindMap', list: 'kindList' }

const go = [
  `// ${HEADER}`,
  '',
  'package when',
  '',
  '// listVariables gives the variables a condition may name, in the order when.json lists them.',
  'func listVariables() []variable {',
  '\treturn []variable{',
  ...variables.map(
    (one) => `\t\t{name: ${JSON.stringify(one.name)}, kind: ${GO_TYPES[one.type]}},`,
  ),
  '\t}',
  '}',
  '',
].join('\n')

const ts = [
  `// ${HEADER}`,
  '',
  '// WHEN_VARIABLES are the variables a when condition may name, with their types.',
  'export const WHEN_VARIABLES = [',
  ...variables.map((one) => `  { name: '${one.name}', type: '${one.type}' },`),
  '] as const',
  '',
].join('\n')

write('../../../plugin/catalog/when/variables.go', go)
write('../../../plugin/sdk-ts/src/slots/whenVariables.ts', ts)
